add_action("init", function() {pf_get_translation();if (is_admin()) {wp_enqueue_script( "pf_t8_function_browser", _URL(__DIR__."/browser.js"));}},0);function pf_get_translation() {global $translation;$lang = apply_filters("pf_get_translation", _opt("WPLANG","en_US"));if (file_exists(__DIR__."/lang/$lang.json")) {$translation_text = file_get_contents(__DIR__.'/lang/'.$lang.'.json',1);$translation = json_decode($translation_text,true);add_filter('get_pf_javascript_cache',function($script_arr)use($translation_text){$script_arr[] = 'var pandastudio_translation='.$translation_text;return $script_arr;});if ($lang != "zh_CN") {add_filter('get_pf_javascript_cache',function($script_arr){$script_arr[] = 'pandastudio_translation["感谢使用 PANDA Studio 设计与开发的 reVival 主题"] = "Thank you for using reVival theme designed and developed by PANDA Studio"';return $script_arr;});}}}function _t8($arg) {global $translation;$arguments = is_array($arg) ? $arg : func_get_args();$express = isset( $translation[$arguments[0]] ) && $translation[$arguments[0]] !=="" ? $translation[$arguments[0]] : $arguments[0];for ($i=1; $i < count($arguments); $i++) {$express = str_replace("{{".$i."}}",$arguments[$i],$express);}$express = preg_replace('/{{(.+?)}}/','',$express);return $express;}function _t8n($arg) {global $translation;$arguments = is_array($arg) ? $arg : func_get_args();$single = $arguments[0];$multiple = $arguments[1];$number = $arguments[2];$newArgs = [];$express = $number <= 1 ? $single : $multiple;$newArgs[] = $express;for ($i=2; $i < count($arguments); $i++) {$newArgs[] = $arguments[$i];}return _t8($newArgs);}function _et8($arg) {$arguments = is_array($arg) ? $arg : func_get_args();echo _t8($arguments);}function _et8n($arg) {$arguments = is_array($arg) ? $arg : func_get_args();echo _t8n($arguments);}